TP.register({id:"lp1-g1",lp:1,grade:"1",mode:"baseline",nextGrade:"2nd grade",build(E){const F=E.F,dirHtml=E.dir,note=E.note;const ico=(n,px)=>(F.icon||F.pic2)(n,px)||n;const INK="#6B4A3C",PUPIL="#4A332A",BLUSH="#F49AAB";const kEye=(x,y,r)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${PUPIL}"/>`;const kBlush=(x,y,r)=>`<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${(r*1.5).toFixed(1)}" ry="${(r*.95).toFixed(1)}" fill="${BLUSH}" opacity=".88"/>`;const kSmile=(x,y,w,sw)=>`<path d="M${(x-w).toFixed(1)} ${y.toFixed(1)} q${w.toFixed(1)} ${(w*1.05).toFixed(1)} ${(w*2).toFixed(1)} 0" fill="none" stroke="${PUPIL}" stroke-width="${sw.toFixed(1)}" stroke-linecap="round"/>`;const kFace=(cx,cy,r)=>kEye(cx-r*.38,cy-r*.06,r*.16)+kEye(cx+r*.38,cy-r*.06,r*.16)+kBlush(cx-r*.72,cy+r*.3,r*.17)+kBlush(cx+r*.72,cy+r*.3,r*.17)+kSmile(cx,cy+r*.3,r*.21,Math.max(1.3,r*.1));const kCounter=(x,y,r,fill)=>{const base=`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="${Math.max(1.8,r*.16).toFixed(1)}"/>`;return r<9?base:base+kFace(x,y,r)};const kStar=(cx,cy,R,fill,withFace)=>{let d="";for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?R*.45:R;d+=(i?"L":"M")+(cx+Math.cos(a)*rr).toFixed(1)+" "+(cy+Math.sin(a)*rr).toFixed(1)+" "}return`<path d="${d}Z" fill="${fill}" stroke="${INK}" stroke-width="${(R*.13).toFixed(1)}" stroke-linejoin="round" stroke-linecap="round"/>`+(withFace?kFace(cx,cy+R*.06,R*.44):"")};const FABLE="Fox had a big red hat, and he wore it every sunny day. It was his very best hat. One windy morning, Fox went for a walk by the pond. Whoosh! The wind snatched the hat right off his head and tossed it up into a tall tree. Fox jumped and jumped, but he could not reach it. Duck saw what happened. She flew up to the branch, grabbed the hat, and brought it back down. “Thank you, Duck!” said Fox. “You are a good friend.”";const FROG="Frogs live near ponds, where the grass is wet and the water is close. A frog starts its life as an egg. The egg floats in the water until it hatches, and out comes a tadpole. A tadpole has a tail and swims like a fish. As it gets bigger, it grows legs, and its tail gets shorter. At last it hops out of the water and onto land. A frog has a long, sticky tongue. It flicks its tongue out very fast to catch bugs.";const BEES="Honeybees live together in a hive. Worker bees fly from flower to flower to collect nectar. They use the nectar to make honey. Bees also help flowers grow by carrying pollen. A bee does a wiggle dance to show the other bees where the flowers are.";const WORDS=["ship","chin","cake","bike","rain","seed","jumped","sunset","rabbit","said","thap","bame"];function tens(t,o){return F.blocks(0,t,o)}function clip(x,y){return`<rect x="${x+2}" y="${y}" width="56" height="18" rx="9" fill="#D7DEE3" stroke="${INK}" stroke-width="3"/><rect x="${x+10}" y="${y+5}" width="40" height="8" rx="4" fill="none" stroke="${INK}" stroke-width="2"/>`}function measureFig(){let a=`<svg viewBox="0 0 330 90" width="330" role="img" aria-label="Pencil measured with paper clips"><polygon points="0,20 260,20 300,32 260,44 0,44" fill="#FBD873" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/><rect x="0" y="20" width="22" height="24" rx="7" fill="#F4796F" stroke="${INK}" stroke-width="3"/>${kFace(76,32,15)}`;for(let i=0;i<5;i++)a+=clip(i*60,58);a+="</svg>";let b=`<svg viewBox="0 0 330 90" width="330" role="img" aria-label="Crayon with paper clips spaced apart"><polygon points="0,20 200,20 236,32 200,44 0,44" fill="#8ECBE8" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/>${kFace(66,32,15)}`;for(let i=0;i<3;i++)b+=clip(i*88,58);b+="</svg>";return`<div class="figure"><div>${a}<p class="fig-label">Pencil</p></div><div>${b}<p class="fig-label">Crayon</p></div></div>`}function sharesFig(){const c=`<svg viewBox="0 0 160 160" width="160" role="img" aria-label="Circle cut into 4 equal parts, 1 shaded"><circle cx="80" cy="80" r="70" fill="#FDF6E6"/><path d="M80 80 L80 10 A70 70 0 0 1 150 80 Z" fill="#F5D33C"/><circle cx="80" cy="80" r="70" fill="none" stroke="${INK}" stroke-width="4"/><line x1="80" y1="10" x2="80" y2="150" stroke="${INK}" stroke-width="4" stroke-linecap="round"/><line x1="10" y1="80" x2="150" y2="80" stroke="${INK}" stroke-width="4" stroke-linecap="round"/></svg>`;const ra=`<svg viewBox="0 0 200 120" width="200" role="img" aria-label="Rectangle cut into 2 unequal parts"><rect x="5" y="5" width="190" height="110" fill="#FDF6E6" stroke="${INK}" stroke-width="4" stroke-linejoin="miter"/><line x1="60" y1="5" x2="60" y2="115" stroke="${INK}" stroke-width="4"/></svg>`;const rb=`<svg viewBox="0 0 200 120" width="200" role="img" aria-label="Rectangle cut into 2 equal parts"><rect x="5" y="5" width="190" height="110" fill="#FDF6E6" stroke="${INK}" stroke-width="4" stroke-linejoin="miter"/><line x1="100" y1="5" x2="100" y2="115" stroke="${INK}" stroke-width="4"/></svg>`;return`<div class="figure"><div>${c}<p class="fig-label">Circle</p></div><div>${ra}<p class="fig-label">Rectangle A</p></div><div>${rb}<p class="fig-label">Rectangle B</p></div></div>`}function digital(t){return`<svg viewBox="0 0 200 90" width="200" role="img" aria-label="Digital clock showing ${t}"><rect x="4" y="4" width="192" height="82" rx="22" fill="#F6DCBE" stroke="${INK}" stroke-width="3.4"/><rect x="18" y="12" width="164" height="46" rx="11" fill="#3B3340" stroke="${INK}" stroke-width="3"/><text x="100" y="38" text-anchor="middle" dominant-baseline="central" font-family="monospace" font-weight="700" font-size="46" fill="#7CF29A">${t}</text>`+kEye(84,70,4.4)+kEye(116,70,4.4)+kBlush(64,74,5.3)+kBlush(136,74,5.3)+kSmile(100,74,4,2.6)+`</svg>`}function starArray(rows,cols){let s=`<svg viewBox="0 0 ${cols*70+20} ${rows*70+20}" width="${cols*70+20}" role="img" aria-label="${rows} rows of ${cols} stars">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){s+=kStar(c*70+45,r*70+41,26,"#FBD873",true)}return s+"</svg>"}function dots(n,seed){const pts=[];let x=seed;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[30+rnd()*220,30+rnd()*180];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>34))pts.push(p)}return`<svg viewBox="0 0 280 240" width="280" role="img" aria-label="Group of dots"><rect x="4" y="4" width="272" height="232" rx="22" fill="none" stroke="var(--line)" stroke-width="3"/>`+pts.map(p=>kCounter(+p[0].toFixed(0),+p[1].toFixed(0),13,"#8ECBE8")).join("")+"</svg>"}function clock(h,m){const cx=130,cy=124,R=108;let s=`<svg viewBox="0 0 260 260" width="260" role="img" aria-label="Analog clock">`;s+=`<path d="M${cx-62} ${cy+R-14} l-12 34 M${cx+62} ${cy+R-14} l12 34" stroke="${INK}" stroke-width="11" stroke-linecap="round"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+9}" fill="#F3DCC4" stroke="${INK}" stroke-width="5"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="#FDF6E6" stroke="${INK}" stroke-width="4"/>`;for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*76}" y="${cy-Math.cos(a)*76}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="${PUPIL}" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:12;s+=`<line x1="${cx+Math.sin(a)*(R-4)}" y1="${cy-Math.cos(a)*(R-4)}" x2="${cx+Math.sin(a)*(R-4-l)}" y2="${cy-Math.cos(a)*(R-4-l)}" stroke="${INK}" stroke-width="${i%5?1.5:3}" stroke-linecap="round"/>`}s+=F.dialFace(cx,cy+34,33);const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*52}" y2="${cy-Math.cos(ha)*52}" stroke="${PUPIL}" stroke-width="9" stroke-linecap="round"/>`;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*84}" y2="${cy-Math.cos(ma)*84}" stroke="#4E8FA3" stroke-width="5" stroke-linecap="round"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="7" fill="${PUPIL}"/>`;return s+`</svg>`}function coinFace(C,r){return`<circle cx="${(C-r*.3).toFixed(1)}" cy="${(C-r*.46).toFixed(1)}" r="${(r*.11).toFixed(1)}" fill="${PUPIL}"/><circle cx="${(C+r*.3).toFixed(1)}" cy="${(C-r*.46).toFixed(1)}" r="${(r*.11).toFixed(1)}" fill="${PUPIL}"/>`+kBlush(C-r*.62,C-r*.2,r*.133)+kBlush(C+r*.62,C-r*.2,r*.133)}function coin(name,r,fill){const C=r+4;return`<svg viewBox="0 0 ${r*2+8} ${r*2+8}" width="${r*2+8}" role="img" aria-label="${name}"><circle cx="${C}" cy="${C}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="3"/><circle cx="${C}" cy="${C}" r="${r-4}" fill="none" stroke="${INK}" stroke-width="1.4" opacity=".45"/>${coinFace(C,r)}<text x="${C}" y="${C+r*.22}" font-size="${Math.max(12,r/2.6)}" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="${PUPIL}">${name}</text></svg>`}function graphHtml(){const data=[["Dogs",6],["Cats",4],["Fish",E.state.fish||0]],cell=40,x0=70,y0=30,rows=8;let s=`<svg viewBox="0 0 400 440" width="400" role="img" aria-label="Bar graph of favorite pets">`;s+=`<text x="220" y="20" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" font-size="22" fill="var(--ink)">Our Favorite Pets</text>`;for(let r=0;r<=rows;r++){const y=y0+10+(rows-r)*cell;s+=`<line x1="${x0}" y1="${y}" x2="${x0+data.length*100}" y2="${y}" stroke="var(--line)" stroke-width="2"/><text x="${x0-12}" y="${y}" text-anchor="end" dominant-baseline="central" font-size="18" fill="var(--ink)">${r}</text>`}data.forEach((d,i)=>{const bx=x0+i*100+20;for(let r=0;r<rows;r++){const y=y0+10+(rows-r-1)*cell,filled=r<d[1];if(i===2)s+=`<rect class="oc" data-r="${r+1}" x="${bx}" y="${y}" width="60" height="${cell}" rx="6" fill="${filled?"#FBD873":"transparent"}" stroke="${filled?INK:"#5E8FA8"}" stroke-dasharray="${filled?"0":"4 4"}" stroke-width="2" style="cursor:pointer"/>`;else if(filled)s+=`<rect x="${bx}" y="${y}" width="60" height="${cell}" rx="6" fill="#8ECBE8" stroke="${INK}" stroke-width="2"/>`}s+=`<text x="${bx+30}" y="${y0+10+rows*cell+26}" text-anchor="middle" font-size="18" font-weight="700" fill="var(--ink)">${d[0]}</text>`});return s+"</svg>"}const STOPS=[{id:1,title:"Sound Game",parts:[{std:["RF.1.2"],n:6,dur:75,html:()=>`<p class="huge" aria-hidden="true">${ico("ear",96)}</p>`,key:["Blend: /s/ /t/ /o/ /p/ (stop)","Blend: /f/ /l/ /a/ /g/ (flag)","What is the middle sound in mud? (/u/)","What are the first and last sounds in ship? (/sh/ and /p/)","Say all the sounds in frog. (/f/ /r/ /o/ /g/)","Long or short vowel: kite? hop? (kite long, hop short; both needed)"]}]},{id:2,title:"Word Flip",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:105,key:["Read each word. thap and bame are silly words: listen for th and the silent e.","Watch for: digraphs (ship, chin), final e (cake, bike), vowel teams (rain, seed), ending -ed (jumped), two syllables (sunset, rabbit), tricky word (said).","Optional: ask how many syllables are in rabbit (2). Add to notes."]}]},{id:3,title:"Read the Story",parts:[{std:["RF.1.4"],kind:"fable",n:73,label:"words read correctly",dur:120,html:()=>`<p class="passage">${FABLE}</p>`,picSup:true,fig:()=>`<div class="figure"><img alt="Fox waves up at Duck, who holds his red hat on a tree branch" style="max-width:100%;width:560px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,key:["73 words. Mark errors and self-corrections on the large-print passage in the record sheet.","Note pace, expression, and whether the student rereads to fix mistakes."]}]},{id:4,title:"Story Questions",parts:[{title:"Story Questions",std:["RL.1.1"],dur:90,picSup:true,fig:()=>`<div class="figure"><img alt="Fox waves up at Duck, who holds his red hat on a tree branch" style="max-width:100%;width:560px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>`<p class="passage">${FABLE}</p>`,qs:["What did the wind do to Fox’s hat?","What did Fox do to try to get his hat?","Who helped Fox? What did she do?","Ask me a question about the story."],key:["Blew it up into a tall tree (RL.1.1)","Jumped and jumped (RL.1.1)","Duck flew up to the branch and got the hat (RL.1.1)","Asks a real question about the story (RL.1.1)"]},{wt:"opinion",gxHome:13,title:"Opinion Writing",std:["W.1.1","W.1.8","L.1.1"],n:7,label:"checks met",dur:180,picSup:true,fig:()=>`<div class="figure" style="margin:10px 0"><img alt="A fox looks up at a tree. A duck on a branch holds the fox's red hat in her beak. Wind blows the leaves." style="max-width:100%;width:600px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,html:()=>`<p class="big">Was Duck a good friend to Fox? Write what you think and tell why. Use the story.</p><ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul><details class="look-back" open><summary>Look back at the story</summary><p class="passage" style="font-size:1.5rem">${FABLE}</p></details>`,key:["Names the story or topic (W.1.1)","States an opinion (W.1.1)","Gives a reason (W.1.1)","Uses a detail from the story to answer (W.1.8)","Gives some sense of closure (W.1.1)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]},{title:"Sentence Detective",std:["RF.1.1"],dur:30,html:()=>`<p class="passage" style="font-size:1.4rem">${FABLE}</p>`,qs:["Find the first word of any sentence. Read that word to me. How do you know a sentence starts there?","Find the end of any sentence. What is the mark at the end called?"],key:["Reads the first word of a sentence and says it starts with a capital letter (RF.1.1)","Finds a period, exclamation mark, or question mark and names it (RF.1.1)"]}]},{id:5,title:"Fix It Fast",parts:[{std:["L.1.1"],dur:60,qs:["Today I walk. Yesterday I ____.","Today I jump. Tomorrow I ____ jump.","He hops. We ____.","Pick the right word: Mia has a dog. It is ____ dog. (she, her, or hers)","Put these together: I like cats. I like dogs.","Make it a question: The frog is green."],key:["walked","will","hop","her","I like cats and dogs. (or uses but, or, so)","Is the frog green?"]}]},{id:6,title:"Tell Me About It",short:"Tell Me",parts:[{std:["SL.1.4"],n:3,label:"checks met",dur:60,html:()=>`<p class="big">Tell me about your favorite place.</p><ul class="qlist" style="margin-top:14px"><li>What do you see there?</li><li>What do you do there?</li><li>How do you feel there?</li></ul>`,key:["Names the place and gives 2 or more details about what is there (SL.1.4)","Names 2 or more people, things, or events at the place and tells something about one of them (SL.1.4)","Says how the place makes them feel, in at least 1 complete sentence, and every detail given stays on this one place (SL.1.4)"]}]},{id:7,title:"Animal Facts",parts:[{title:"Frog Facts",std:["RI.1.1"],dur:75,html:()=>`<p class="passage">${FROG}</p>`,picSup:true,fig:()=>`<div class="figure"><img alt="A frog in a pond catching a bug with its tongue. Below it, five steps in a row: egg, tadpole, tadpole with legs, young frog, adult frog." style="max-width:100%;width:700px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,qs:["What hatches out of a frog egg?","What does a frog use to catch bugs?","Ask me one question about frogs."],key:["A tadpole (RI.1.1)","Its long, sticky tongue (RI.1.1)","Asks a real question about frogs (RI.1.1)"]},{wt:"facts",gxHome:13,title:"Facts Writing",std:["W.1.2","W.1.8","L.1.1"],n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write about frogs. Tell 2 facts you learned from Frog Facts.</p><ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul><details class="look-back" open><summary>Look back at Frog Facts</summary><p class="passage" style="font-size:1.5rem">${FROG}</p></details>`,key:["Names the topic (W.1.2)","Gives at least 2 facts (W.1.2)","Facts come from the Frog Facts passage (W.1.8)","Gives some sense of closure (W.1.2)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]},{title:"Listen Up",std:["SL.1.2"],n:4,dur:75,read:BEES,picSup:true,html:()=>"",fig:()=>`<div class="figure"><img alt="Bees by a hive in a tree. One bee dances in a figure eight and a speech bubble shows flowers. Another bee has yellow pollen on its legs." style="max-width:100%;width:700px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,key:["What do bees make from nectar? (honey) (SL.1.2)","How does a bee show other bees where the flowers are? (wiggle dance) (SL.1.2)","“Ask me one question about bees.” (asks 1 question that is about what was read and starts with a question word: who, what, where, when, why, or how, such as: Where do bees put the honey?) (SL.1.2)","What do bees carry that helps flowers grow? (pollen) (SL.1.2)"]}]},{id:8,title:"Number Fun",parts:[{title:"Count On",std:["1.OA.C.5"],dur:30,qs:["Start at 7. Count on 3. Where do you land? What adding sentence is that?","Start at 12. Count back 2. What taking away sentence is that?"],key:["8, 9, 10. 7 + 3 = 10 (1.OA.C.5)","11, 10. 12 - 2 = 10 (1.OA.C.5)"]},{title:"Count to 120",std:["1.NBT.A.1"],dur:75,qs:["Count out loud from 96 to 112.","Read these numbers out loud: 58, 104, 119.","Write the number one hundred seven.","Count the dots. Write the number that tells how many."],fig2:()=>`<div class="figure">${dots(14,7)}</div>`,key:["96, 97 ... 99, 100, 101 ... 112. Watch the jump past 99 (1.NBT.A.1)","Fifty-eight, one hundred four, one hundred nineteen (1.NBT.A.1)","107, not 1007 (1.NBT.A.1)","14 (1.NBT.A.1)"]},{title:"Tens and Ones",std:["1.NBT.B.2"],dur:30,fig:()=>`<div class="figure">${tens(4,6)}</div>`,qs:["What number is this? How many tens and ones?","What does the 1 in 15 mean?"],key:["46. 4 tens and 6 ones (1.NBT.B.2)","1 ten, or 10 (1.NBT.B.2)"]}]},{id:9,title:"Word Problems",parts:[{title:"Word Problems",std:["1.OA.A.1"],dur:60,picSup:true,fig:()=>"",qfig:[()=>`<div class="figure" style="margin:10px 0"><img alt="Eli has 9 shells and finds some more to make 15. Shell groups of 9 and 6 make 15, shown with 9 cubes plus 6 cubes equals 1 ten and 5 ones. The number sentence reads 9 plus a box equals 15." style="max-width:100%;width:640px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,()=>`<div class="figure" style="margin:10px 0"><img alt="Ana has 12 stickers shown as stars and Ben has 8. Blocks show a ten and 2 ones above 8 ones. The number sentence reads 12 minus 8 equals a box." style="max-width:100%;width:640px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`],qs:["Eli has 9 shells. He finds some more. Now he has 15. How many did he find? Write a number sentence with a box for the number you don’t know.","Ana has 12 stickers. Ben has 8. How many more stickers does Ana have?"],key:["9 + □ = 15 or 15 - 9 = □; answer 6 (1.OA.A.1)","4 (1.OA.A.1)"]},{title:"Number Tricks",std:["1.OA.B.3"],dur:30,qs:["8 + 3 = 11. So what is 3 + 8?","Add 4 + 7 + 6. Which two numbers would you add first? Why?"],key:["11, knows without counting (1.OA.B.3)","17. Adds 4 + 6 to make 10, then 10 + 7 (1.OA.B.3)"]}]},{id:10,title:"Big Adding",parts:[{title:"Big Adding",std:["1.NBT.C.4"],dur:60,picSup:true,fig:()=>"",qfig:[()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Base ten blocks: 3 tens rods and 4 ones cubes, plus 5 ones cubes." style="max-width:100%;width:520px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Base ten blocks: 4 tens rods and 6 ones cubes, plus 2 tens rods." style="max-width:100%;width:520px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Base ten blocks: 2 tens rods and 7 ones cubes, plus 8 ones cubes." style="max-width:100%;width:520px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`],qs:["34 + 5","46 + 20","27 + 8. Show how you did it."],key:["39 (1.NBT.C.4)","66, adds tens to tens (1.NBT.C.4)","35, makes a new ten (drawing, tens and ones, or 27 + 3 + 5) and explains (1.NBT.C.4)"]},{title:"Take Away Tens",std:["1.NBT.C.6"],dur:30,picSup:true,fig:()=>"",qfig:[()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Base ten blocks: 7 tens rods minus 3 tens rods." style="max-width:100%;width:520px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Base ten blocks: 9 tens rods minus 5 tens rods." style="max-width:100%;width:520px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`],qs:["70 - 30","90 - 50. Show how you know."],key:["40 (1.NBT.C.6)","40, uses tens (9 tens take away 5 tens) and explains (1.NBT.C.6)"]}]},{id:11,title:"Pet Graph",parts:[{std:["1.MD.C.4"],kind:"graph",n:3,dur:60,html:()=>`<p class="big" style="margin-top:0">3 kids like fish. Finish the graph.</p>`,render:()=>`<div class="figure">${graphHtml()}</div>`,bind:(root,ctx)=>root.querySelectorAll(".oc").forEach(r=>r.onclick=()=>{const v=+r.dataset.r;E.state.fish=(E.state.fish||0)===v?v-1:v;E.save();ctx.redraw()}),qs:["How many kids are on the graph in all?","How many more kids like dogs than cats?"],key:["Fish bar filled to 3. Click the squares as the student tells you.","6 + 4 + 3 = 13 kids in all","Dogs (6) minus cats (4) = 2 more"]}]},{id:12,title:"Measure, Time, and Shapes",short:"Measure",parts:[{title:"Measure It",std:["1.MD.A.2"],dur:30,fig:()=>`<div class="figure" style="margin:6px 0 12px"><img alt="Question 1: How many paper clips long is the pencil? A pencil is lined up above a row of paper clips. Question 2: Is the crayon measured the right way? A crayon is lined up above three paper clips with gaps between them." style="max-width:100%;width:640px;height:auto;border-radius:14px" src="data:image/webp;base64,"></div>`,qs:["How many paper clips long is the pencil?","Is the crayon measured the right way? Why or why not?"],key:["5 paper clips (1.MD.A.2)","No. The clips have gaps between them (1.MD.A.2)"]},{title:"Clock Time",std:["1.MD.B.3"],dur:40,fig:()=>`<div class="figure"><div>${clock(3,30)}<p class="fig-label">Clock A</p></div><div>${clock(9,0)}<p class="fig-label">Clock B</p></div><div>${digital("6:30")}<p class="fig-label">Clock C</p></div></div>`,qs:["Write the time on Clock A.","Write the time on Clock B.","Read Clock C out loud. On a clock with hands, where would the short hand point at that time?"],key:["3:30 (1.MD.B.3)","9:00 (1.MD.B.3)","6:30. Short hand between 6 and 7 (1.MD.B.3)"]},{title:"Fair Shares",std:["1.G.A.3"],dur:70,fig:()=>sharesFig(),qsup:[null,null,()=>`<div class="figure" style="margin:6px 0 12px"><img alt="A half of a pizza and a fourth of the same pizza, side by side." style="max-width:100%;width:420px;height:auto" src="data:image/webp;base64,"></div>`],qs:["What do we call the yellow part of the circle?","Which rectangle shows halves? How do you know?","Which is bigger: half of a pizza or a fourth of the same pizza?","Draw a rectangle on your paper. Cut it into 4 equal parts. Hold it up."],key:["A fourth, a quarter, or one of four equal parts (1.G.A.3)","B. The parts are the same size (1.G.A.3)","Half. More parts means smaller parts (1.G.A.3)","Draws a rectangle with 4 parts that are about the same size (1.G.A.3)"]}]},{id:13,title:"Write About It",short:"Write",parts:[{wt:"story",title:"Story Writing",std:["W.1.3","L.1.1"],n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write about a time something blew away or got lost. Tell what happened first, next, and last.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>`,key:["Tells 2 or more events in order (W.1.3)","Includes some details about what happened (W.1.3)","Uses time words like first, next, then (W.1.3)","Gives some sense of closure (W.1.3)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]}]},{id:14,title:"Copy an Animal Part",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first two out loud. Draw the third on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A duck walks over soft wet mud. It walks all day. It does not sink. Its feet are wide and flat.</p>
     <div class="figure">${ico("duck",104)}${ico("turtle",104)}</div>
     <p class="big">The crew cross the beach. They carry a heavy load. They sink into the soft sand. It happens every time.</p>`,qs:["How do wide, flat feet help a duck stay on top of soft mud?","Draw a sand shoe for the crew that copies the duck's wide, flat foot.","Tell me which animal part you copied and how your shoe keeps a boot from sinking."],key:["The weight is spread out over a bigger space, so the foot presses down less in any one spot. Any answer about spreading the weight or being wide counts.","Any shoe drawn wider and flatter than a boot: a board, a paddle shape, a flat oval strapped on. A shoe drawn the same size as a boot is partial, so ask what the duck's foot is like.","Needs both halves: names the duck's wide flat foot as the part copied, and says the wide shape spreads the weight so the boot does not press down into the sand."]}]},{id:15,title:"Parents and Young",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"High in a palm tree on the island, a parrot has a nest with two young in it. All morning the parent flies out and comes back with seeds. Every time it lands on the edge of the nest, the two young open their beaks wide and the parent drops a seed in. When the wind picks up off the water, the parent gives one short call. The young settle down low in the nest and stay there. When the wind drops, the parent calls again in a soft voice, and the young pop back up.",qs:["What do the young do every single time the parent lands on the nest?","What do the young do when they hear the one short call?","How does settling down low in the nest help the young when the wind picks up?"],key:["They open their beaks wide. The point is that it happens every time, which is what makes it a pattern.","They settle down low in the nest and stay there until the soft call.","Low in the nest they are out of the wind and cannot be tipped or blown off the branch. Any answer about staying put and staying in the nest counts."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the two pairs. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A young palm and a grown palm. A young parrot and a grown parrot.</p>
     <div class="figure">${ico("sprout",92)}${ico("palm",104)}</div>
     <div class="figure">${ico("chick",92)}${ico("parrot",104)}</div>`,qs:["Name one way the young palm is like the grown palm.","Name one way the young palm is not exactly like the grown palm.","The young parrot and the grown parrot are both birds with beaks and wings. Does that mean the young one looks exactly like its parent? Say how you know from the picture."],key:["Both have a green stem and leaves, both are plants, both grow out of the ground. Any likeness the picture shows counts.","The young one is much shorter, it has fewer leaves, it has no trunk yet. Any difference the picture shows counts.","No. They are alike in big ways, beak and wings and feathers, but the young one is smaller and its feathers are not the same. The word to listen for is like but not exactly."]}]},{id:16,title:"Sun, Moon and Stars",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">The crew wrote down the sky for four days.</p>
     <table class="bigTable"><tr><th>Day</th><th>Where the sun came up</th><th>Where the sun went down</th></tr>
     <tr><td>Monday</td><td>over the east point</td><td>behind the west rocks</td></tr>
     <tr><td>Tuesday</td><td>over the east point</td><td>behind the west rocks</td></tr>
     <tr><td>Wednesday</td><td>over the east point</td><td>behind the west rocks</td></tr>
     <tr><td>Thursday</td><td>over the east point</td><td>behind the west rocks</td></tr></table>
     <div class="figure">${ico("sun",84)}${ico("island",84)}${ico("star",84)}</div>`,qs:["Where did the sun come up on every one of the four days?","Where did the sun go down on every one of the four days?","Friday morning is coming. Where do you predict the sun will come up, and how do you know?","The crew also sees one bright star over the north point every clear night. Where do you predict that star will be tomorrow night?"],key:["over the east point","behind the west rocks","over the east point. The reason has to come from the log: it did the same thing all four days, so it is a pattern that repeats.","over the north point. Same reasoning: it has been in the same place every clear night, so it can be predicted."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">The crew counted the hours of daylight four times in one year.</p>
     <table class="bigTable"><tr><th>Time of year</th><th>Hours of daylight</th></tr>
     <tr><td>summer</td><td>14</td></tr><tr><td>fall</td><td>12</td></tr>
     <tr><td>winter</td><td>10</td></tr><tr><td>spring</td><td>12</td></tr></table>`,qs:["Which time of year had the most hours of daylight?","Which time of year had the fewest?","In winter, does it get dark earlier in the evening or later than it does in summer? Use the chart to say how you know."],key:["summer, 14 hours","winter, 10 hours","earlier. Winter has only 10 hours of daylight and summer has 14, so the light runs out sooner in winter."]}]},{id:17,title:"Sound and Shaking",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a rubber band and a box, try the first part first. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Stretch a rubber band across an open box. Pluck it once and watch it closely while you listen.</p>
     <div class="figure">${ico("box",96)}${ico("pan",96)}</div>
     <p class="big">Now put a few grains of dry sand on a piece of cloth pulled tight. Bang a pan hard right next to the cloth, without touching it.</p>`,qs:["While you hear the sound, what is the rubber band doing?","Now pinch the band so it cannot move. What happens to the sound, and why?","When the pan is banged next to the tight cloth, what do the grains of sand do?","So can a sound make something move, even when nothing touches it? Say how the sand answers that."],key:["Shaking back and forth very fast. Buzzing, wobbling, vibrating, blurry, all count.","The sound stops. Nothing is shaking any more, and no shaking means no sound.","They hop or jump or skitter on the cloth.","Yes. The sound from the pan made the cloth shake, and the shaking cloth tossed the sand. The evidence is the sand moving when nothing touched it."]}]},{id:18,title:"Seeing in the Dark",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The hold under the deck has no window. When the hatch is shut, no light gets in at all.</p>
     <div class="figure">${ico("chest",100)}${ico("torch",100)}</div>`,qs:["The chest is sitting in the hold with the hatch shut. Can you see it? Say why or why not.","What do you need to bring down there so you can see the chest?","A black cloth is in a room with no light at all. If you wait a long time, will your eyes finally see it? Say what is really needed."],key:["No. There is no light in the hold, and you cannot see a thing unless light shines on it and comes back to your eyes.","A light: a lantern or a flashlight. Accept opening the hatch to let light in.","No. Waiting does not help if there is no light at all. Light has to shine on the cloth. The color of the cloth is not the reason."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">The crew shone one flashlight beam at four things and wrote down what the beam did.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear glass bottle</td><td>went straight through</td></tr>
     <tr><td>a thin sail cloth</td><td>a little came through, blurry</td></tr>
     <tr><td>a wooden board</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a polished tin plate</td><td>bounced back the other way</td></tr></table>`,qs:["Which thing let almost all the light go straight through?","Which thing stopped the light and made a dark shadow?","The thin sail cloth let a little light through. Could you see the shape of something behind it clearly, or only a blur?","You want to send the flashlight beam around a corner. Which of the four would you use, and why?"],key:["the clear glass bottle","the wooden board","only a blur. Some light gets through the cloth, but not enough to see a clear shape.","the polished tin plate, because it bounces the beam back in a new direction. Any answer naming the shiny plate and bouncing counts."]}]},{id:19,title:"A Message Far Away",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The lookout stands up high. The hill top is where he stands. The rest of the crew is below. They are on the beach. It is far down. They are much too far apart. They cannot shout that far.</p>
     <div class="figure">${ico("telescope",96)}${ico("lantern",96)}${ico("megaphone",96)}</div>`,qs:["Draw a device the lookout could use to tell the beach crew that the boat is back. It has to use light or sound.","Tell me what you drew and whether it uses light or sound.","Tell me the one message your device sends, and how the beach crew will know that is what it means."],key:["Any device that makes light or sound carry: a lantern held up, a mirror catching the sun, a horn, a bell, a drum, a whistle. A written sign does not count, because writing cannot be read from that far.","Names it and says which one it uses. Light for a lantern or a mirror, sound for a horn or a bell.","Needs a message and an agreed meaning: two flashes means the boat is back, one long horn means come up. The agreement is the part that makes it a code and not just a noise."]}]},{id:20,title:"Fix the Blowing Map",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"Every time the crew spreads the paper map out on the deck table, the wind off the water lifts one corner and folds it over. They have to stop and smooth it flat again, and the map gets one more crease across it each time.",qs:["What is the problem the crew wants to change?","Ask me one question that would help you fix it.","Name one thing you would watch or measure first, before you build anything."],key:["The wind keeps lifting a corner of the map and folding it over.","Any real question: which corner lifts, how strong is the wind, how big is the map, is the table flat, is there anything heavy nearby. A statement is not a question, so ask once more.","Any real observation: which corner goes first, which way the wind comes from, how heavy the map is, how often it happens in a morning."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that holds the map flat on the table while the wind blows.</p>
     <div class="figure">${ico("map",96)}${ico("anchor",96)}${ico("box",96)}</div>`,qs:["Draw your fix on the map and the table.","Point to the part that does the holding and tell me its shape.","Tell me why that shape works better than laying another flat sheet of paper on top."],key:["Any holder that would really hold: a heavy stone on each corner, a rim or frame round the edge, clips, a strip of wood along the top, a clear sheet weighted down.","Names a shape: round and heavy, a long bar, a hook that grips over the edge, a frame all the way round.","Because the shape adds weight or grips the edge, and a flat sheet of paper has no weight and no grip, so the wind lifts it too."]}]},{id:21,title:"Which Fix Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">The crew built two map holders and tested each one in ten gusts of wind. They counted how many times a corner lifted.</p>
     <table class="bigTable"><tr><th>Holder</th><th>Times a corner lifted, out of 10</th></tr>
     <tr><td>four smooth stones</td><td>1</td></tr>
     <tr><td>one strip of tape</td><td>6</td></tr></table>`,qs:["Which holder worked better in the test?","How do you know, using the numbers in the chart?","One of the crew says the tape is better because it looks tidier. Is that a reason to say the tape worked better? Say why or why not."],key:["the four smooth stones","A corner lifted only 1 time out of 10 with the stones and 6 times out of 10 with the tape, so the stones held better. The numbers have to be in the answer.","No. Looking tidier is not a test result. The chart is what tells you which one held the map, and the chart says the stones."]}]},{id:22,title:"Rights and Jobs",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and naming a responsibility that goes with a right",read:"The crew keeps two lists side by side on the cabin wall. The first list says Rights. Every person gets a turn with the spyglass. Every person gets a safe place to sleep. Every person can say what they think at the morning meeting. The second list says Responsibilities. Put your tools back where you found them. Help carry the water up from the stream. Listen while someone else is talking.",qs:["Name one right from the first list.","Name one responsibility from the second list.","What is the difference between a right and a responsibility?","You have the right to say what you think at the meeting. What is your responsibility while someone else is saying what they think?"],key:["A turn with the spyglass, a safe place to sleep, or saying what you think at the meeting.","Putting tools back, helping carry the water, or listening while someone else talks.","A right is something you get. A responsibility is something you do, a job you are counted on for. Any wording that holds that difference counts.","To listen, and to wait for your turn. This is the one that shows the two lists go together."]}]},{id:23,title:"Where Things Are",short:"Map Grid",parts:[{std:["HSS-1.2"],n:6,dur:110,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, telling a physical feature from a built one, naming the ocean a place sits in, and knowing how many continents and oceans the world has",html:()=>`<p class="big">A map of the island, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ico("palm",56)}</td><td></td><td>${ico("wave",56)}</td></tr>
     <tr><th>B</th><td></td><td>${ico("cabin",56)}</td><td></td></tr>
     <tr><th>C</th><td>${ico("chest",56)}</td><td></td><td>${ico("mountain",56)}</td></tr></table>
     <p class="big">${ico("palm",48)} palm tree &nbsp; ${ico("wave",48)} the Pacific Ocean &nbsp; ${ico("cabin",48)} the cabin &nbsp; ${ico("chest",48)} the supply chest &nbsp; ${ico("mountain",48)} the hill</p>
     <p class="big">The top of this map is north. The bottom is south, the right is east, and the left is west.</p>`,qs:["Find the cabin. Give its exact spot on the grid, the letter and the number.","Where is the palm tree compared to the cabin? Use north, south, east or west.","Name one thing on this map that nature put there.","Look at the map. Which ocean is this island in?","How many continents does the whole world have?","How many oceans does the whole world have?"],key:["B2. Both parts are needed. B alone or 2 alone is partial. (HSS-1.2)","North of the cabin and west of it. Both directions are needed for a full answer, and north west counts. (HSS-1.2)","The palm tree, the Pacific Ocean, or the hill. (HSS-1.2)","The Pacific Ocean. It is named in the map legend, so point to the legend if the student is stuck. (HSS-1.2)","Seven (HSS-1.2)","Four (HSS-1.2)"]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud about your own neighborhood.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">Think about the street you live on and the streets near it.</p>
     <div class="figure">${ico("cabin",88)}${ico("bus",88)}${ico("bridge",88)}</div>`,qs:["Name two things in your neighborhood that people built.","People who live on the same street often came from many different places. Name one thing a family might bring with them from the place they used to live.","Name one way two families on the same street might be different from each other, and one way they might be the same."],key:["Any two built things: houses, a store, a school, a road, a sidewalk, a park bench, a fire station, a bus stop. A tree or a hill does not count here.","Any real answer: the language they speak at home, the food they cook, a song, a game, the way they say hello.","Needs both halves. A difference such as the language at home, the food, the number of people. A sameness such as they both live on this street, both have children at the same school, both shop at the same store."]}]},{id:24,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"telling what a national symbol stands for and naming a tradition that shows people belong to the same country",html:()=>`<p class="big">A flag stands for a country. The United States flag has 50 stars. It has 13 stripes. The bald eagle stands for the country. That country is the United States.</p>
     <div class="figure">${ico("flag",110)}${ico("eagle",110)}</div>`,qs:["How many stars are on the flag of the United States, and what does each one stand for?","What does a symbol do? Does it stand for something bigger, or is it only a picture?","Name one thing people in the United States do together at a school or at a ball game that shows they all belong to the same country."],key:["50 stars, one for each state.","It stands for something bigger. The flag is cloth, but it stands for the whole country.","Saying the Pledge of Allegiance, singing the national anthem, standing up while the flag goes past, raising the flag in the morning."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Finding your way across the water.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>finding the way</td><td>the stars and a compass</td><td>a screen that shows the map</td></tr>
     <tr><td>sending word home</td><td>a letter that rode on a ship for weeks</td><td>a message that arrives in a second</td></tr>
     <tr><td>what the water is</td><td>salty, with waves and wind</td><td>salty, with waves and wind</td></tr></table>
     <div class="figure">${ico("compass",88)}${ico("phone",88)}</div>`,qs:["Long ago, how did a sailor find the way across the water?","How does someone find the way across the water today?","Name one thing in the chart that changed from long ago to today.","Name one thing in the chart that stayed the same."],key:["By the stars and a compass.","With a screen that shows the map. Accept a phone, a map on a screen, or a satellite.","Finding the way changed, or sending word home changed. Either counts.","The water itself: still salty, still has waves and wind. This is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Big Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,html:()=>`<div style="text-align:center">${["rainbow","unhappy","careful"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["rainbow (two syllables, vowel teams)","unhappy (prefix un-)","careful (suffix -ful)"]},4:{id:"L4",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,html:()=>`<p class="passage" style="font-size:1.5rem">${FABLE}</p><ol class="qlist"><li>Why couldn’t Fox get his hat back by himself?</li><li>How did Fox feel at the end? How do you know?</li></ol>`,key:["The hat was up in a tall tree and he could not reach it","Glad or thankful. He said thank you and called Duck a good friend"]},9:{id:"L9",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,html:()=>`<p class="big">Max had 30 toy cars. He got 15 more. Then he gave 9 away. How many cars does Max have now?</p>`,key:["36 (30 + 15 = 45, then 45 - 9 = 36)"]},10:{id:"L10",lv:true,title:"Level Up: Bigger Adding",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:2,html:()=>`<ol class="qlist"><li>47 + 36</li><li>62 - 25</li></ol>`,key:["83","37"]},12:{id:"L12",lv:true,title:"Level Up: Time Challenge",std:["2.MD.C.7"],needs:["1.MD.B.3"],n:2,html:()=>`<div class="figure">${clock(4,25)}</div><ol class="qlist"><li>What time is it?</li><li>You see this time after school. Is it a.m. or p.m.?</li></ol>`,key:["4:25","p.m."]}};const DIRS={"1.0":"Listen to your teacher. Say the sounds and words out loud.","7.2":"Listen carefully. Your teacher will read about bees. Then answer out loud.","2.0":"Read each word out loud. The last two are silly words. Just sound them out.","3.0":"Read the story out loud. Use your best reading voice.","4.0":"Listen to each question. Answer out loud.","4.2":"Look at the story again. Answer out loud.","5.0":"Listen to your teacher read each one. Say your answer out loud.","6.0":"Talk for about one minute. Speak clearly.","7.0":"Read about frogs out loud. Then answer out loud.","8.0":"Answer out loud.","8.1":"Count and read out loud. Write your numbers on your paper and hold it up.","8.2":"Look at the blocks. Answer out loud.","9.0":"Listen to each problem. You can draw on your paper. Hold it up when you finish.","9.1":"Answer out loud. Tell how you know.","10.0":"Solve each one. Say 1 and 2 out loud. Show your work for 3 on your paper and hold it up.","10.1":"Solve each one. Tell how you know.","11.0":"Tell your teacher how many squares to color for fish. Then answer out loud.","12.0":"Look at the pictures. Answer out loud.","12.1":"Write the times for A and B on your paper and hold it up.","12.2":"Look at the shapes. Answer out loud. Draw the last one on your paper.","4.1":"Write on your paper. When you finish, hold it up and read it to your teacher.","7.1":"Write on your paper. When you finish, hold it up and read it to your teacher.","13.0":"Write on your paper. When you finish, hold it up and read it to your teacher.","L2":"Read each word out loud.","L4":"Answer out loud. Use the story.","L9":"Solve on your paper. Tell your teacher the answer.","L10":"Solve on your paper and hold it up.","L12":"Look at the clock. Answer out loud."};STOPS.forEach(st=>st.parts.forEach((p,i)=>{const d=DIRS[st.id+"."+i];if(d)p.dir=d;else if(!p.dir)p.dir=""}));Object.values(LEVELUPS).forEach(l=>{l.dir=DIRS[l.id]||""});const DESC={"1.0":"blending and segmenting sounds in spoken words","2.0":"reading words with digraphs, final e, vowel teams, endings, and two syllables","3.0":"a 73-word grade-level story read aloud","4.0":"key detail questions about a story","4.2":"finding the first word and end mark of a sentence","5.0":"spoken grammar items (verb tense, pronouns, joining sentences, questions)","6.0":"describing a favorite place with details","7.0":"key detail questions about an informational text","7.2":"asking and answering questions after listening to a text read aloud","8.0":"counting on and back to add and subtract","8.1":"counting, reading, and writing numbers to 120","8.2":"tens and ones in two-digit numbers","9.0":"addition and subtraction word problems within 20","9.1":"using properties of addition as strategies","10.0":"adding within 100","10.1":"subtracting multiples of 10","11.0":"finishing and reading a bar graph with three categories","12.0":"measuring length with same-size units","12.1":"telling time to the hour and half hour","12.2":"halves and fourths of circles and rectangles","4.1":"an opinion writing piece","7.1":"an informative writing piece","13.0":"a narrative writing piece"};STOPS.forEach(st=>st.parts.forEach((p,i)=>{const d=DESC[st.id+"."+i];if(d)p.desc=d;else if(!p.desc)p.desc=""}));const LOG_NAMES_UNUSED={readq:"Questions read aloud",passage:"Passage read aloud",repeat:"Directions repeated or reworded",objects:"Counters, fingers, or real objects",time:"Extra time",scribe:"Adult wrote the student’s words",brk:"Break"};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},blk=[0,0],c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function blkHtml(){return`<div class="blk-row"><button class="chip" data-b="0" data-d="1">Add a ten</button><button class="chip" data-b="0" data-d="-1">Take a ten</button><button class="chip" data-b="1" data-d="1">Add a one</button><button class="chip" data-b="1" data-d="-1">Take a one</button><button class="chip" data-b="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]?tens(blk[0],blk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} tens and ${blk[1]} ones on the mat.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I think ____.","One reason is ____.","In the story, ____.","That is why ____."],facts:["Frogs ____.","One fact is ____.","Another fact is ____.","Now you know about ____."],story:["One day, ____.","First, ____.","Next, ____.","Last, ____.","I felt ____."]};function sentHtml(st){const wt=st.parts&&st.parts[0].wt||"opinion";return`<ul class="starters">${STARTERS[wt].map(x=>`<li>${x}</li>`).join("")}</ul>`}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{if(x.dataset.b==="x")blk=[0,0];else{const i=+x.dataset.b;blk[i]=Math.max(0,Math.min(i?19:9,blk[i]+ +x.dataset.d))}r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.2","W.1.3"],msg:"If an adult wrote for the student, do not rate the printing check for L.1.1."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
